  "type": "module",
  "scripts": {
    "test": "vitest run",
    "build": "node scripts/build.js",
    "validate": "node scripts/validate.js",
    "enrich": "node scripts/enrich.js",
    "all": "npm run test && npm run validate && npm run build"
  },
  "keywords": [],
  "author": "",
