import { describe, it, expect } from 'vitest';
import { ParameterSchema, InstallationSchema, ServerSchema } from '../schemas/server-entry.js';

describe('Schemas', () => {
  describe('ParameterSchema', () => {
    it('should validate a valid parameter', () => {
      const validParameter = {
        name: 'API Key',
        key: 'API_KEY',
        description: 'Your API key',
        placeholder: 'sk-1234567890',
        required: true
      };

      expect(() => ParameterSchema.parse(validParameter)).not.toThrow();
    });

    it('should set default for required field', () => {
      const parameter = {
        name: 'API Key',
        key: 'API_KEY'
      };

      const result = ParameterSchema.parse(parameter);
      expect(result.required).toBe(true);
    });

    it('should reject invalid parameters', () => {
      expect(() => ParameterSchema.parse({})).toThrow();
      expect(() => ParameterSchema.parse({ name: '' })).toThrow();
      expect(() => ParameterSchema.parse({ name: 'Test' })).toThrow(); // missing key
    });
  });

  describe('InstallationSchema', () => {
    it('should validate a valid installation', () => {
      const validInstallation = {
        name: 'NPX',
        description: 'Run using NPX',
        config: '{"command": "npx", "args": ["test"]}',
        prerequisites: ['Node.js']
      };

      expect(() => InstallationSchema.parse(validInstallation)).not.toThrow();
    });

    it('should validate minimal installation', () => {
      const installation = {
        name: 'Docker',
        config: '{"command": "docker"}'
      };

      expect(() => InstallationSchema.parse(installation)).not.toThrow();
    });
  });

  describe('ServerSchema', () => {
    it('should validate a complete server entry', () => {
      const validServer = {
        id: 'test_server',
        name: 'Test Server',
        description: 'A test server',
        author: 'Test Author',
        url: 'https://github.com/test/server',
        license: 'MIT',
        category: 'development',
        tags: ['test', 'example'],
        installations: [{
          name: 'NPX',
          config: '{"command": "npx", "args": ["${TEST_PARAM}"]}', // references TEST_PARAM
          parameters: [{
            name: 'Test Param',
            key: 'TEST_PARAM'
          }],
          transports: ['stdio']
        }],
        featured: false,
        verified: true,
      };

      expect(() => ServerSchema.parse(validServer)).not.toThrow();
    });

    it('should set default values', () => {
      const minimalServer = {
        id: 'minimal',
        name: 'Minimal Server',
        description: 'A minimal server',
        author: 'Test',
        url: 'https://example.com',
        category: 'test',
        tags: ['test'],
        installations: [{
          name: 'Test',
          config: '{}',
          transports: ['stdio']
        }]
      };

      const result = ServerSchema.parse(minimalServer);
      expect(result.featured).toBe(false);
      expect(result.verified).toBe(false);
    });

    it('should enforce description length limit', () => {
      const longDescription = 'a'.repeat(201);
      const server = {
        id: 'test',
        name: 'Test',
        description: longDescription,
        author: 'Test',
        url: 'https://example.com',
        category: 'test',
        tags: ['test'],
        installations: [{
          name: 'Test',
          config: '{}',
          transports: ['stdio']
        }]
      };

      expect(() => ServerSchema.parse(server)).toThrow();
    });

    it('should require at least one installation', () => {
      const server = {
        id: 'test',
        name: 'Test',
        description: 'Test',
        author: 'Test',
        url: 'https://example.com',
        category: 'test',
        tags: ['test'],
        installations: []
      };

      expect(() => ServerSchema.parse(server)).toThrow();
    });

    it('should reject invalid transports', () => {
      const server = {
        id: 'test',
        name: 'Test',
        description: 'Test',
        author: 'Test',
        url: 'https://example.com',
        category: 'test',
        tags: ['test'],
        installations: [{
          name: 'Test',
          config: '{}',
          transports: ['invalid-transport']
        }]
      };

      expect(() => ServerSchema.parse(server)).toThrow();
    });

    it('should accept valid transports', () => {
      const server = {
        id: 'test',
        name: 'Test',
        description: 'Test',
        author: 'Test',
        url: 'https://example.com',
        category: 'test',
        tags: ['test'],
        installations: [{
          name: 'Test',
          config: '{}',
          transports: ['stdio', 'sse', 'streamable-http']
        }]
      };

      expect(() => ServerSchema.parse(server)).not.toThrow();
    });
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'fs/promises';
import path from 'path';
import yaml from 'js-yaml';

const TEST_SERVERS_DIR = 'test/fixtures/servers';
const TEST_DIST_DIR = 'test/fixtures/dist';

describe('Build Process', () => {
  beforeEach(async () => {
    // Create test directories
    await fs.mkdir(TEST_SERVERS_DIR, { recursive: true });
    await fs.mkdir(TEST_DIST_DIR, { recursive: true });
  });

  afterEach(async () => {
    // Clean up test files
    try {
      await fs.rm('test/fixtures', { recursive: true, force: true });
    } catch (error) {
      // Ignore cleanup errors
    }
  });

  it('should build registry from valid server files', async () => {
    // Create a test server file
    const testServer = {
      id: 'test_server',
      name: 'Test Server',
      description: 'A test server for testing',
      author: 'Test Author',
      url: 'https://github.com/test/server',
      category: 'test',
      tags: ['test'],
      installations: [{
        name: 'NPX',
        config: '{"command": "npx", "args": ["test"]}',
        transports: ['stdio']
      }]
    };

    await fs.writeFile(
      path.join(TEST_SERVERS_DIR, 'test-server.yaml'),
      yaml.dump(testServer)
    );

    // Import and run build logic (we'd need to refactor build.js to be testable)
    // For now, let's test the YAML parsing and validation
    const content = await fs.readFile(path.join(TEST_SERVERS_DIR, 'test-server.yaml'), 'utf-8');
    const data = yaml.load(content);

    expect(data.id).toBe('test_server');
    expect(data.name).toBe('Test Server');
    expect(data.installations).toHaveLength(1);
  });

  it('should handle multiple server files', async () => {
    const servers = [
      {
        id: 'server_one',
        name: 'Server One',
        description: 'First test server',
        author: 'Test',
        url: 'https://example.com',
        category: 'test',
        tags: ['test'],
        installations: [{
          name: 'Test',
          config: '{}',
          transports: ['stdio']
        }]
      },
      {
        id: 'server_two',
        name: 'Server Two',
        description: 'Second test server',
        author: 'Test',
        url: 'https://example.com',
        category: 'test',
        tags: ['test'],
        installations: [{
          name: 'Test',
          config: '{}',
          transports: ['stdio']
        }]
      }
    ];

    for (let i = 0; i < servers.length; i++) {
      await fs.writeFile(
        path.join(TEST_SERVERS_DIR, `server-${i + 1}.yaml`),
        yaml.dump(servers[i])
      );
    }

    const files = await fs.readdir(TEST_SERVERS_DIR);
    const yamlFiles = files.filter(f => f.endsWith('.yaml'));

    expect(yamlFiles).toHaveLength(2);
  });

  it('should ignore non-YAML files', async () => {
    await fs.writeFile(path.join(TEST_SERVERS_DIR, 'readme.txt'), 'This is not a YAML file');
    await fs.writeFile(path.join(TEST_SERVERS_DIR, 'test.json'), '{"not": "yaml"}');

    const testServer = {
      id: 'valid_server',
      name: 'Valid Server',
      description: 'A valid server',
      author: 'Test',
      url: 'https://example.com',
      category: 'test',
      tags: ['test'],
      installations: [{
        name: 'Test',
        config: '{}',
        transports: ['stdio']
      }]
    };

    await fs.writeFile(
      path.join(TEST_SERVERS_DIR, 'valid.yaml'),
      yaml.dump(testServer)
    );

    const files = await fs.readdir(TEST_SERVERS_DIR);
    const yamlFiles = files.filter(f => f.endsWith('.yaml') || f.endsWith('.yml'));

    expect(files).toHaveLength(3); // All files
    expect(yamlFiles).toHaveLength(1); // Only YAML files
  });
});

import { describe, it, expect } from 'vitest';
import { getCurrentTimestamp, isValidServerId, sanitizeToId } from '../scripts/utils.js';

describe('Utils', () => {
  describe('getCurrentTimestamp', () => {
    it('should return a unix timestamp', () => {
      const timestamp = getCurrentTimestamp();
      expect(typeof timestamp).toBe('number');
      expect(timestamp).toBeGreaterThan(0);
      // Should be within the last second
      expect(Math.abs(Date.now() / 1000 - timestamp)).toBeLessThan(1);
    });
  });

  describe('isValidServerId', () => {
    it('should accept valid server IDs', () => {
      expect(isValidServerId('filesystem')).toBe(true);
      expect(isValidServerId('brave_search')).toBe(true);
      expect(isValidServerId('my_server_123')).toBe(true);
      expect(isValidServerId('ABC123')).toBe(true);
    });

    it('should reject invalid server IDs', () => {
      expect(isValidServerId('fs')).toBe(false); // too short
      expect(isValidServerId('file-system')).toBe(false); // contains dash
      expect(isValidServerId('file system')).toBe(false); // contains space
      expect(isValidServerId('file@system')).toBe(false); // contains special char
      expect(isValidServerId('file.system')).toBe(false); // contains dot
      expect(isValidServerId('')).toBe(false); // empty
    });
  });

  describe('sanitizeToId', () => {
    it('should convert names to valid IDs', () => {
      expect(sanitizeToId('File System')).toBe('File_System');
      expect(sanitizeToId('brave-search')).toBe('brave_search');
      expect(sanitizeToId('My Cool Server!')).toBe('My_Cool_Server');
      expect(sanitizeToId('test@example.com')).toBe('testexamplecom');
    });

    it('should handle edge cases', () => {
      expect(sanitizeToId('___test___')).toBe('test');
      expect(sanitizeToId('   spaced   ')).toBe('spaced');
      expect(sanitizeToId('multiple   spaces')).toBe('multiple_spaces');
      expect(sanitizeToId('multiple___underscores')).toBe('multiple_underscores');
    });

    it('should preserve valid characters', () => {
      expect(sanitizeToId('valid_id_123')).toBe('valid_id_123');
      expect(sanitizeToId('ABC123')).toBe('ABC123');
    });
  });
});

